<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { quizApi } from '@/api'
import { errorMessage } from '@/api/client'
import type { Question, Answer, QuizAttempt } from '@/types'
const route = useRoute(), router = useRouter(), id = String(route.params.attemptId)
const attempt = ref<QuizAttempt | null>(null), questions = ref<Question[]>([]), answers = ref<Record<string, Answer>>({}), revision = ref(0), index = ref(0)
const loading = ref(true), saving = ref(false), submitting = ref(false), error = ref(''), dialog = ref(false), saveState = ref('答案自动保存')
const current = computed(() => questions.value[index.value])
const unanswered = computed(() => questions.value.filter(q => !answers.value[q.id]))
const answeredCount = computed(() => questions.value.length - unanswered.value.length)
const busy = computed(() => saving.value || submitting.value)
const selected = computed(() => current.value ? answers.value[current.value.id]?.optionId : null)
async function syncAnswers() { const saved = (await quizApi.getAnswers(id)).data; answers.value = Object.fromEntries(saved.answers.map(a => [a.questionId, a])); revision.value = saved.revision }
async function load() { loading.value = true; error.value = ''; try { attempt.value = (await quizApi.getAttempt(id)).data; if (attempt.value.status === 'submitted') { await router.replace(`/result/${id}`); return }; questions.value = (await quizApi.getQuestions(id)).data; await syncAnswers(); const firstMissing = questions.value.findIndex(q => !answers.value[q.id]); index.value = firstMissing >= 0 ? firstMissing : Math.max(0, questions.value.length - 1) } catch(e) { error.value = errorMessage(e) } finally { loading.value = false } }
async function choose(optionId: string) { if (!current.value || busy.value || selected.value === optionId) return; const questionId = current.value.id; saving.value = true; error.value = ''; saveState.value = '正在保存…'; try { const data = (await quizApi.saveAnswer(id, questionId, optionId, revision.value)).data; answers.value[questionId] = data.answer; revision.value = data.revision; saveState.value = '已保存' } catch(e) { error.value = errorMessage(e); saveState.value = '保存未确认，请重选或刷新'; try { await syncAnswers() } catch { /* 保留页面供重试 */ } } finally { saving.value = false } }
function go(next: number) { if (busy.value || next < 0 || next >= questions.value.length) return; index.value = next; dialog.value = false; window.scrollTo({ top: 0, behavior: 'smooth' }) }
async function submit() { if (busy.value || unanswered.value.length) return; submitting.value = true; error.value = ''; try { attempt.value = (await quizApi.submit(id, revision.value)).data; await router.replace(`/result/${id}`) } catch(e) { error.value = errorMessage(e); dialog.value = false; try { await syncAnswers() } catch { /* 重试或刷新 */ } } finally { submitting.value = false } }
onMounted(load)
</script>
<template><div class="container page"><div v-if="loading" class="center"><span class="loading"></span><p>正在恢复答题进度…</p></div><template v-else-if="current"><div class="quiz-top"><span>{{ attempt?.productSlug === 'city-quiz' ? '灵魂城市测评' : '心理年龄测评' }}</span><span>{{ answeredCount }} / {{ questions.length }} 已答</span></div><div class="progress-track" role="progressbar" :aria-valuenow="answeredCount" :aria-valuemax="questions.length" aria-valuemin="0" aria-label="答题进度"><div :style="{ width: `${answeredCount / questions.length * 100}%` }"></div></div><div class="quiz-top"><p class="eyebrow">第 {{ index + 1 }} / {{ questions.length }} 题 · {{ current.dimensionName }}</p><span class="save-state" role="status">{{ saveState }}</span></div><article class="card question-card"><h1 class="question-title">{{ current.text }}</h1><div class="options" role="group" aria-label="答案选项"><button v-for="option in current.options" :key="`${current.id}-${option.id}`" class="option-btn" :class="{ selected: selected === option.id }" :aria-pressed="selected === option.id" :disabled="busy" @click="choose(option.id)"><span class="option-letter">{{ option.id }}</span><span>{{ option.text }}</span><span v-if="selected === option.id" class="option-check" aria-hidden="true">✓</span></button></div></article><p v-if="error" class="error-message" role="alert">{{ error }}</p><div class="actions"><button class="btn btn-secondary" :disabled="busy || index === 0" @click="go(index - 1)">上一题</button><button v-if="index < questions.length - 1" class="btn btn-primary" :disabled="busy || !selected" @click="go(index + 1)">下一题</button><button v-else class="btn btn-primary" :disabled="busy" @click="dialog = true">检查并提交</button></div><details class="card question-directory"><summary>答题目录 · 查看进度</summary><div class="question-grid"><button v-for="(q, i) in questions" :key="q.id" class="question-number" :class="{ answered: answers[q.id], current: index === i }" :aria-label="`跳到第${i + 1}题${answers[q.id] ? '，已答' : '，未答'}`" :disabled="busy" @click="go(i)">{{ i + 1 }}</button></div></details><p class="muted small">已保存的答案会保留。离开后可使用专属密码继续。</p><div v-if="dialog" class="dialog-overlay"><section class="card stack dialog" role="dialog" aria-modal="true" aria-labelledby="submit-title"><h2 id="submit-title">确认提交答卷</h2><template v-if="unanswered.length"><p>还有 {{ unanswered.length }} 道题未回答：</p><div class="question-grid"><button v-for="q in unanswered" :key="q.id" class="question-number" @click="go(questions.indexOf(q))">{{ q.sequence }}</button></div></template><p v-else>全部 {{ questions.length }} 道题已保存。提交后不能修改答案，可以反复查看报告。</p><div class="actions"><button class="btn btn-secondary" :disabled="busy" @click="dialog = false">继续检查</button><button class="btn btn-primary" :disabled="busy || unanswered.length > 0" @click="submit">{{ submitting ? '正在生成报告…' : '确认提交' }}</button></div></section></div></template><div v-else class="card stack"><p class="error-message" role="alert">{{ error || '暂时无法加载答卷' }}</p><button class="btn btn-secondary" @click="load">重新加载</button><router-link to="/access">输入密码恢复权限</router-link></div></div></template>
